// Assemble widgets in dependency order (topological)
const deps={"sig-header": [], "sig-nav": ["sig-header"], "sig-main": ["sig-nav"]};
const order=[],seen={};
const visit=n=>{if(seen[n])return;seen[n]=1;(deps[n]||[]).forEach(visit);order.push(n);};
Object.keys(deps).forEach(visit);
console.log('assemble order:',order.join(' -> '));

